NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'I Thessalonians'

CHAPTERS = {
    1: {
        1: '§ Pavel in Silván ter Timótej cerkvi Tesaloníčanov, ki je v Bogu Očetu in v Gospodu Jezusu Kristusu: ›Milost bodi vam in mir od Boga, našega Očeta in Gospoda Jezusa Kristusa.‹',
        2: 'Vedno se za vas vse zahvaljujemo Bogu in vas omenjamo v svojih molitvah,',
        3: 'ko se brez prenehanja spominjamo vašega dela vere in truda ljubezni ter potrpežljivosti upanja v našega Gospoda Jezusa Kristusa, pred očmi Boga in našega Očeta;',
        4: 'ker poznamo, ljubljeni bratje, vašo izvolitev od Boga.',
        5: 'Kajti naš evangelij ni prišel k vam samo v besedi, temveč tudi v moči in v Svetem Duhu in v precejšnjem zagotovilu; kakor veste, kakšne vrste ljudje smo bili med vami zaradi vas.',
        6: 'In vi ste postali naši in Gospodovi sledilci, ker ste besedo sprejeli v veliki stiski, z veseljem Svetega Duha,',
        7: 'tako da ste bili zgledi vsem, ki verujejo v Makedoniji in Ahaji.',
        8: 'Kajti od vas je odmevala Gospodova beseda ne samo po Makedoniji in Ahaji, temveč se je vaša, do Boga usmerjena vera, razširila tudi naokoli, po vsakem kraju; tako da nam ni treba karkoli govoriti,',
        9: 'kajti oni sami so o nas prikazali kakšne vrste prihod smo imeli k vam in kako ste se od malikov obrnili k Bogu, da služite živemu in resničnemu Bogu;',
        10: 'in da čakate na njegovega Sina iz nebes, ki ga je obudil od mrtvih, celó Jezusa, ki nas je osvobodil pred besom, ki pride.',
    },
    2: {
        1: 'Kajti bratje, vi sami veste, da naš prihod k vam ni bil zaman,',
        2: 'temveč smo celó potem, ko smo poprej v Filípih trpeli in bili sramotno obravnavani, kakor veste, smo bili v našem Bogu pogumni, da smo vam v velikem boju izpričali Božji evangelij.',
        3: 'Kajti naše spodbujanje ni bilo iz prevare niti iz nečistosti niti v zvijači,',
        4: 'temveč kakor nam je Bog dopustil, da nam zaupa evangelij, točno tako govorimo; ne kakor ugajajoči ljudem, temveč Bogu, ki preizkuša naša srca.',
        5: 'Kajti niti nismo ob kateremkoli času uporabili laskavih besed, kakor veste niti pretveze pohlepnosti; Bog je priča.',
        6: 'Niti nismo iskali slave od ljudi niti od vas niti ne od drugih, ko bi lahko bili obremenjujoči kot Kristusovi apostoli.',
        7: 'Toda med vami smo bili nežni, tako kakor dojilja neguje svoje otroke.',
        8: 'Tako smo vas bili vdano željni, da smo vam bili voljni podeliti ne samo Božji evangelij, ampak tudi naše duše, ker ste nam bili dragi.',
        9: 'Kajti spomnite se, bratje, našega truda in muke; kajti ponoči in podnevi smo garali, ker nismo želeli biti obremenitev komurkoli izmed vas, ko smo vam pridigali Božji evangelij.',
        10: 'Vi ste priče in tudi Bog, kako sveto in pravično in neoporečno smo se vêdli med vami, ki verujete.',
        11: 'Prav tako veste, kako smo tolažili in opozarjali vsakega izmed vas, tako kakor oče počne svojim otrokom,',
        12: 'da bi vi živeli vredno Boga, ki vas je poklical v svoje kraljestvo in slavo.',
        13: 'Zaradi tega razloga se prav tako brez prenehanja zahvaljujemo Bogu, kajti ko ste prejeli Božjo besedo, ki ste jo slišali od nas, je niste sprejeli kakor človeško besedo, temveč takšno, kot je v resnici, Božjo besedo, ki učinkovito deluje tudi v vas, ki verujete.',
        14: 'Kajti vi, bratje, ste postali sledilci Božjih cerkvá, ki so v Judeji v Kristusu Jezusu; kajti tudi vi ste trpeli podobne stvari od svojih lastnih rojakov, takšne, kot so jih oni od Judov,',
        15: 'ki so ubili tako Gospoda Jezusa kakor svoje lastne preroke in so preganjali nas; pa ne ugajajo Bogu in so nasprotni vsem ljudem.',
        16: 'Branijo nam govoriti poganom, da bi bili le-ti lahko rešeni in da bi vsakič dopolnili svoje grehe; kajti bes je prišel nadnje do skrajnosti.',
        17: 'Toda mi, bratje, ki smo bili za kratek čas vzeti od vaše navzočnosti, [toda] ne v srcu, smo si z velikim hrepenenjem toliko obilneje prizadevali, da vidimo vaše obličje.',
        18: 'Zato smo želeli priti k vam, celó jaz Pavel, enkrat in ponovno; toda Satan nas je zadržal.',
        19: 'Kajti kaj je naše upanje ali veselje ali krona radosti? Ali ne celó vi v prisotnosti našega Gospoda Jezusa Kristusa ob njegovem prihodu?',
        20: 'Kajti vi ste naša slava in veselje.',
    },
    3: {
        1: 'Zato, ko nismo mogli več potrpeti, smo mislili, da je dobro, da v Atenah ostanemo sami,',
        2: 'in smo poslali Timóteja, našega brata in Božjega služabnika in našega sodelavca pri Kristusovem evangeliju, da vas utrdi in da vas potolaži glede vaše vere,',
        3: 'da ne bi bil noben človek omajan s temi stiskami, kajti vi sami veste, da smo določeni za to.',
        4: 'Kajti resnično, ko smo bili z vami, smo vam vnaprej povedali, da naj bi trpeli stisko; kakor se je zgodilo in vi to veste.',
        5: 'Zaradi tega razloga, ko nisem mogel več potrpeti, sem poslal, da spoznam vašo vero, da vas ne bi z nekimi načini skušal skušnjavec in bi bil naš trud zaman.',
        6: 'Toda sedaj, ko je od vas k nam prišel Timótej in nam prinesel dobre novice o vaši veri ter ljubezni in da nas imate vedno v lepem spominu ter si silno želite, da nas vidite, kakor si tudi mi [želimo] videti vas;',
        7: 'zato smo bili, bratje, po vaši veri potolaženi glede vas v vsej naši stiski in tegobi,',
        8: 'kajti zdaj živimo, če vi trdno stojite v Gospodu.',
        9: 'Kajti kakšne zahvale lahko spet za vas vrnemo Bogu, za vse veselje, s katerim se zaradi vas veselimo pred svojim Bogom?',
        10: 'Ponoči in podnevi silno prosimo, da bi lahko videli vaš obraz in lahko dovršili to, kar primanjkuje vaši veri.',
        11: 'Torej sam Bog in naš Oče in naš Gospod Jezus Kristus [naj] našo pot usmerjata k vam.',
        12: 'In Gospod [naj] vam stori, da rastete in [ste] obilni v ljubezni drug do drugega in do vseh ljudi, prav tako kakor mi počnemo vam,',
        13: 'z namenom, da bi lahko vaša srca utrdil brez graje v svetosti pred Bogom, celó našim Očetom, ob prihodu našega Gospoda Jezusa Kristusa z vsemi njegovimi svetimi.',
    },
    4: {
        1: 'Nadalje vas potem rotimo, bratje in vas spodbujamo po Gospodu Jezusu, da kakor ste od nas prejeli, kako bi morali živeti in ugajati Bogu, tako da bi bili bolj in bolj obilni.',
        2: 'Kajti veste, kakšne zapovedi smo vam dali po Gospodu Jezusu.',
        3: 'Kajti to je Božja volja, celó vaše posvečenje, da naj bi se vzdržali pred prešuštvovanjem,',
        4: 'da bi vsakdo izmed vas vedel, kako čuvati svojo posodo v posvečenju in časti;',
        5: 'ne [pa] v poželenju pohotnosti, tako kakor pogani, ki ne poznajo Boga;',
        6: 'da noben človek ne gre preko in ne goljufa svojega brata v katerikoli zadevi; zato ker je Gospod maščevalec vsega tega, kakor smo vas tudi mi svarili in pričevali.',
        7: 'Kajti Bog nas ni poklical k nečistosti, temveč v svetost.',
        8: 'Kdor torej prezira, ne prezira človeka, temveč Boga, ki nam je prav tako dal svojega Svetega Duha.',
        9: 'Toda glede bratoljúbja ne potrebujete, da vam pišem, kajti vi sami ste od Boga poučeni, da ljubite drug drugega.',
        10: 'In zares to delajte do vseh bratov, ki so po vsej Makedoniji. Toda rotimo vas, bratje, da bolj in bolj rastete',
        11: 'in da se učite biti mirni ter opravljati svoje lastno opravilo in da delate s svojimi lastnimi rokami, kakor smo vam zapovedali;',
        12: 'da boste lahko živeli iskreno do teh, ki so zunaj in da ne boste ničesar potrebovali.',
        13: 'Toda ne želim, da bi bili vi nevedni, bratje, glede teh, ki so zaspali, da ne žalujete, tako kakor drugi, ki nimajo upanja.',
        14: 'Kajti če verujemo, da je Jezus umrl in ponovno vstal, bo točno tako tudi tiste, ki spijo v Jezusu, Bog privedel z njim.',
        15: 'Kajti to vam rečemo po Gospodovi besedi, da mi, ki smo živi in ostanemo do Gospodovega prihoda, ne bomo vodili teh, ki so zaspali.',
        16: 'Kajti sam Gospod se bo spustil iz nebes z vzklikom, z glasom nadangela in z Božjo trobento; in prvi bodo vstali mrtvi v Kristusu.',
        17: 'Potem pa bomo mi, ki smo živi in preostanemo, vzeti skupaj z njimi v oblake, da srečamo Gospoda v zraku, in tako bomo vedno z Gospodom.',
        18: 'Zato drug drugega tolažite s temi besedami.',
    },
    5: {
        1: 'Toda o časih in obdobjih, bratje, ni potrebno, da vam pišem.',
        2: 'Kajti vi sami prav dobro veste, da dan Gospodov prihaja tako, kakor tat ponoči.',
        3: 'Kajti ko bodo govorili: »Mir in varnost,« tedaj nenadoma pride nadnje uničenje, kakor porodne muke na žensko z otrokom; in ne bodo ubežali.',
        4: 'Toda vi, bratje, niste v temi, da vas tisti dan preseneti kakor tat.',
        5: 'Vi vsi ste otroci svetlobe in otroci dneva. Nismo od noči niti od teme.',
        6: 'Zatorej ne spimo, kakor počno drugi, temveč čujmo in bodimo trezni.',
        7: 'Kajti tisti, ki spijo, spijo ponoči; in tisti, ki se opijajo, so pijani ponoči.',
        8: 'Toda mi, ki smo od dneva, bodimo trezni, nadenimo si prsni oklep vere in ljubezni in za čelado upanje rešitve duše.',
        9: 'Kajti Bog nas ni določil za bes, temveč da dosežemo rešitev duše po našem Gospodu Jezusu Kristusu,',
        10: 'ki je umrl za nas, da bodisi smo budni ali spimo, naj bi živeli skupaj z njim.',
        11: 'Zato se skupaj tolažite in izgrajujte drug drugega, kakor tudi počnete.',
        12: 'In rotimo vas bratje, da spoznate te, ki se med vami trudijo in so nad vami v Gospodu ter vas opominjajo,',
        13: 'in da jih zaradi njihovega dela zelo visoko spoštujte v ljubezni. In bodite v miru med seboj.',
        14: 'Torej vas spodbujamo, bratje, posvarite te, ki so nepodrejeni, tolažite malodušne, podpirajte slabotne, bodite potrpežljivi do vseh ljudi.',
        15: 'Glejte, da nihče nobenemu človeku ne vrača zla za zlo, temveč vedno sledite temu, kar je dobro, tako med seboj kakor do vseh ljudi.',
        16: 'Neprenehoma se veselite.',
        17: 'Molíte brez prenehanja.',
        18: 'V vsaki stvari se zahvaljujte, kajti to je Božja volja v Kristusu Jezusu glede vas.',
        19: 'Ne gasite Duha.',
        20: 'Ne prezirajte prerokovanj.',
        21: 'Preizkušajte vse stvari; trdno držite to, kar je dobro.',
        22: '§ Vzdržite se vsega videza zla.',
        23: 'In sam Bog miru naj vas popolnoma posveti; in prosim Boga, da bodo vaš celoten duh in duša in telo ohranjeni neomadeževani do prihoda našega Gospoda Jezusa Kristusa.',
        24: 'Zvest je on, ki vas kliče, ki bo to tudi storil.',
        25: 'Bratje, molíte za nas.',
        26: 'Pozdravite vse brate s svetim poljubom.',
        27: 'Po Gospodu vam naročam, da bo ta poslanica prebrana vsem svetim bratom.',
        28: 'Milost našega Gospoda Jezusa Kristusa bodi z vami. Amen. [Prva poslanica Tesaloníčanom je bila napisana iz Aten.]',
    },
}
